import base64,zlib,os,subprocess

# Deploy dashboard
d=""
with open('/var/www/luxe-talent/dist/dashboard.html','wb') as f:
    f.write(zlib.decompress(base64.b64decode(d)))
print('dashboard.html deployed')

# Deploy voice.php
v=""
with open('/var/www/luxe-talent/dist/api/voice.php','wb') as f:
    f.write(zlib.decompress(base64.b64decode(v)))
print('voice.php deployed')

# Fix ownership
os.system('chown nginx:nginx /var/www/luxe-talent/dist/dashboard.html /var/www/luxe-talent/dist/api/voice.php')

# Add voice to nginx if needed
nginx = open('/etc/nginx/conf.d/luxe-talent.conf').read()
if '|voice)' not in nginx:
    nginx = nginx.replace('|sms)', '|sms|voice)')
    open('/etc/nginx/conf.d/luxe-talent.conf','w').write(nginx)
    os.system('nginx -t && systemctl restart nginx')
    print('nginx updated with voice')
else:
    print('nginx already has voice')

# Create call_log table
sql = """CREATE TABLE IF NOT EXISTS call_log (
    id INT AUTO_INCREMENT PRIMARY KEY,
    direction ENUM('inbound','outbound') NOT NULL,
    phone VARCHAR(20) NOT NULL,
    performer_email VARCHAR(255) DEFAULT '',
    twilio_sid VARCHAR(50) DEFAULT '',
    status VARCHAR(30) DEFAULT '',
    duration INT DEFAULT 0,
    recording_url VARCHAR(500) DEFAULT '',
    recording_sid VARCHAR(50) DEFAULT '',
    admin_phone VARCHAR(20) DEFAULT '',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_phone (phone),
    INDEX idx_email (performer_email),
    INDEX idx_created (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"""
result = subprocess.run(['mysql','-u','root',"-pSonia@7700",'luxe_talent','-e',sql], capture_output=True, text=True)
if result.returncode == 0:
    print('call_log table created')
else:
    print('DB error: ' + result.stderr)

print('Done!')
